import java.util.*;

class Solution {
    public double myPow(double x, int n) {
        long e = n;                 // long so that -e never overflows
        if (e < 0) { x = 1 / x; e = -e; }
        return pow(x, e);
    }

    private double pow(double x, long e) {
        if (e == 0) return 1.0;
        double half = pow(x, e / 2); // solve the half-size problem once
        return (e % 2 == 0) ? half * half : half * half * x;
    }
}

