class Solution:
    def myPow(self, x: float, n: int) -> float:
        def go(b, e):
            if e == 0: return 1.0
            h = go(b, e // 2)
            return h * h * (b if e % 2 else 1.0)
        return go(x, n) if n >= 0 else 1.0 / go(x, -n)

